<div class="section-head"><div><h2>Submission monitoring</h2><p class="muted">Academic review mode. Untrusted code is never executed by PHP.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Participant</th><th>Contest / Problem</th><th>Language</th><th>Verdict</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($submissions as $s):?><tr><td>#<?=e($s['submission_id'])?></td><td><?=e($s['user_name'])?></td><td><?=e($s['contest_title'])?><br><strong><?=e($s['problem_title'])?></strong></td><td><?=e($s['language'])?></td><td><span class="badge badge-<?=e(strtolower($s['verdict']))?>"><?=e(str_replace('_',' ',$s['verdict']))?></span></td><td><?=e($s['submitted_at'])?></td><td><a class="button-outline button-small" href="<?=e(url('/submissions/'.$s['submission_id']))?>">Review</a></td></tr><?php endforeach;?><?php if(!$submissions):?><tr><td colspan="7" class="empty">No submissions.</td></tr><?php endif;?></tbody></table></div>
